package cl.skinspad.catalogo;
import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;import org.springframework.test.context.DynamicPropertyRegistry;import org.springframework.test.context.DynamicPropertySource;import org.springframework.test.web.servlet.MockMvc;import org.springframework.http.MediaType;
import static org.junit.jupiter.api.Assertions.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;import cl.skinspad.catalogo.domain.*;
@SpringBootTest(properties={"spring.datasource.url=jdbc:h2:mem:moderacion;MODE=MySQL;DB_CLOSE_DELAY=-1","spring.datasource.driver-class-name=org.h2.Driver","spring.jpa.hibernate.ddl-auto=create-drop"}) @AutoConfigureMockMvc
class ModeracionReporteTest {
 static final com.sun.net.httpserver.HttpServer remoto;static{try{remoto=com.sun.net.httpserver.HttpServer.create(new java.net.InetSocketAddress("127.0.0.1",0),0);remoto.createContext("/api/internal/moderacion/usuarios/",x->{byte[] b=("{\"id\":\"actor\",\"rol\":\""+(x.getRequestURI().getPath().endsWith("admin")?"admin":"cliente")+"\",\"suspendido\":false}").getBytes(java.nio.charset.StandardCharsets.UTF_8);x.getResponseHeaders().set("Content-Type","application/json");x.sendResponseHeaders(200,b.length);x.getResponseBody().write(b);x.close();});remoto.start();}catch(Exception e){throw new RuntimeException(e);}}
 @DynamicPropertySource static void props(DynamicPropertyRegistry r){r.add("USUARIO_URL",()->"http://127.0.0.1:"+remoto.getAddress().getPort());}
 @AfterAll static void cerrar(){remoto.stop(0);}
 @Autowired MockMvc mvc;@Autowired cl.skinspad.catalogo.config.InternalApiKey key;@Autowired cl.skinspad.catalogo.repository.ProductoRepository productos;@Autowired cl.skinspad.catalogo.repository.CategoriaRepository categorias;@Autowired cl.skinspad.catalogo.moderacion.AccionReporteRepository acciones;
 Producto item(){var p=new Producto();p.setNombre("AK-47");p.setCategoria(categorias.findAll().get(0));p.setPrecio(java.math.BigDecimal.valueOf(1000));p.setVendedorId("seller");p.setEstado(EstadoProducto.ACTIVO);return productos.saveAndFlush(p);}
 String body(String ref,String actor){return "{\"referencia\":\""+ref+"\",\"actor\":\""+actor+"\",\"motivo\":\"Revisión de soporte\"}";}
 @Test void despublicacionIdempotenteConAuditoria()throws Exception{var p=item();String ref="REP-"+p.getId()+"-ok";for(int i=0;i<2;i++)mvc.perform(post("/api/internal/moderacion/publicaciones/"+p.getId()+"/despublicar").header("X-Skins-Internal",key.value()).contentType(MediaType.APPLICATION_JSON).content(body(ref,"admin"))).andExpect(status().isOk());assertEquals(EstadoProducto.ELIMINADO,productos.findById(p.getId()).orElseThrow().getEstado());assertTrue(acciones.existsById(ref));}
 @Test void credencialYRolYReservaProtegidos()throws Exception{var p=item();String url="/api/internal/moderacion/publicaciones/"+p.getId()+"/despublicar";mvc.perform(post(url).contentType(MediaType.APPLICATION_JSON).content(body("REP-8-x","admin"))).andExpect(status().isForbidden());mvc.perform(post(url).header("X-Skins-Internal",key.value()).contentType(MediaType.APPLICATION_JSON).content(body("REP-8-x","cliente"))).andExpect(status().isForbidden());p.setReservaPago("COMPRA-1");p.setEstado(EstadoProducto.INACTIVO);productos.saveAndFlush(p);mvc.perform(post(url).header("X-Skins-Internal",key.value()).contentType(MediaType.APPLICATION_JSON).content(body("REP-8-x","admin"))).andExpect(status().isConflict());assertFalse(acciones.existsById("REP-8-x"));}
}
